package com.bank.succession;

import java.util.*;
import java.util.logging.*;
import static java.util.Comparator.comparingDouble;
import static java.util.stream.Collectors.*;

public class SecondHighestDemo {
    private static final Logger log = Logger.getLogger("Succession");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> staff = List.of(
            new Employee("Rajesh", "IT", 1000000.0),
            new Employee("Amit", "IT", 800000.0),
            new Employee("Karan", "IT", 600000.0),
            new Employee("Priya", "Sales", 250000.0));  // Sales has only one
        SuccessionService service = new SuccessionService();

        Map<String, Optional<Employee>> deputies = service.secondHighestByDepartment(staff);
        deputies.forEach((dept, opt) -> log.info(() -> dept + " deputy → "
            + opt.map(Employee::getName).orElse("none")));
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final String name;
    private final String department;
    private final double salary;
    Employee(String name, String department, double salary) {
        this.name = name; this.department = department; this.salary = salary;
    }
    String getName() { return name; }
    String getDepartment() { return department; }
    double getSalary() { return salary; }
}

// ─── Would be in service/SuccessionService.java ───
class SuccessionService {
    Map<String, Optional<Employee>> secondHighestByDepartment(List<Employee> staff) {
        return staff.stream()
            .collect(groupingBy(
                Employee::getDepartment,
                collectingAndThen(toList(), list -> list.stream()
                    .sorted(comparingDouble(Employee::getSalary).reversed()) // high→low
                    .skip(1)                                                 // drop top
                    .findFirst())));                                         // runner-up
    }
}
